import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
tok = None
log = {}
def new_token():
    global tok
    r = urllib.request.Request(BASE + "/token", method="POST", data=b"")
    tok = json.load(urllib.request.urlopen(r))["token"]
def get(path):
    global tok
    for attempt in range(200):
        if tok is None: new_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok})
        try:
            with urllib.request.urlopen(req) as r:
                return json.load(r)
        except urllib.error.HTTPError as e:
            body = e.read().decode()[:200]
            log[e.code] = log.get(e.code, 0) + 1
            if e.code == 404: return {"__404": True}
            if e.code == 401:
                new_token(); continue
            wait = e.headers.get("Retry-After")
            if wait is None:
                try: wait = json.loads(body).get("retry_after")
                except Exception: pass
            print(path, e.code, dict(e.headers), body, file=sys.stderr)
            time.sleep(float(wait) if wait else 1)
        except Exception as e:
            log["exc"] = log.get("exc", 0) + 1
            print(path, "EXC", e, file=sys.stderr); time.sleep(1)
    raise SystemExit("gave up " + path)

orders = []
p = 1; total = None
while True:
    d = get(f"/orders?page={p}")
    total = d["total_pages"]
    orders.append(d)
    if not d["next"]: break
    p += 1
json.dump(orders, open("/tmp/recon/pages.json", "w"))
cids = {o["customer_id"] for d in orders for o in d["items"]}
cust = {c: get(f"/customers/{c}") for c in sorted(cids)}
json.dump(cust, open("/tmp/recon/cust.json", "w"))
print("pages", len(orders), "total_pages", total, "customers", len(cust), "errors", log)
EOF
python3 -I /tmp/recon/fetch.py 2>&1 | tail -30

